    return isc_match_filter_reg(_m, str1, (udomain_t*) str2);
}

/*! \brief
 * Wrapper to do isc match filter
 */
static int w_isc_match_filter(struct sip_msg* _m, char* str1, char* str2) {
    return isc_match_filter(_m, str1, (udomain_t*) str2);
}

